import{_ as e,o as a,c as s,ag as o}from"./chunks/framework.BSwSpTvy.js";const p=JSON.parse('{"title":"🔍 Custom Search Endpoint","description":"","frontmatter":{},"headers":[],"relativePath":"features/tools/custom-search.md","filePath":"features/tools/custom-search.md"}'),n={name:"features/tools/custom-search.md"};function i(r,t,l,h,d,c){return a(),s("div",null,[...t[0]||(t[0]=[o(`<h1 id="🔍-custom-search-endpoint" tabindex="-1">🔍 Custom Search Endpoint <a class="header-anchor" href="#🔍-custom-search-endpoint" aria-label="Permalink to &quot;🔍 Custom Search Endpoint&quot;">​</a></h1><p>Registering a Custom Search Endpoint transforms your internal APIs (e.g., Elasticsearch, Algolia, or any generic HTTPS POST search API) into a <strong>native tool call</strong> directly exposed to your configured LLM model.</p><p>This enables you to interact with your data in two ways:</p><hr><h2 id="feature-1-agent-tool-custom-search" tabindex="-1">Feature 1: Agent Tool (<code>custom_search</code>) <a class="header-anchor" href="#feature-1-agent-tool-custom-search" aria-label="Permalink to &quot;Feature 1: Agent Tool (\`custom_search\`)&quot;">​</a></h2><p>By saving your endpoint, the <code>custom_search</code> tool is automatically registered in your LLM&#39;s system prompt. This gives the <strong>configured AI model</strong> the ability to autonomously execute searches against your logs, docs, and internal systems without you having to manually query them.</p><h3 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h3><p>When the agent is working on a task that requires context you haven&#39;t provided yet, the model will dynamically invoke the <code>custom_search</code> tool call. You will see the tool execution appear in the Agent Panel as a collapsible card, just like any other native Zed tool (<code>read_file</code>, <code>terminal</code>, etc.).</p><h3 id="when-the-model-uses-it" tabindex="-1">When the model uses it <a class="header-anchor" href="#when-the-model-uses-it" aria-label="Permalink to &quot;When the model uses it&quot;">​</a></h3><p>The model will use this tool when you ask things like:</p><ul><li>&quot;Find all error logs from the last deployment&quot;</li><li>&quot;Search my index for documents about user authentication&quot;</li><li>&quot;What does our system contain about payment failures?&quot;</li></ul><h3 id="permission" tabindex="-1">Permission <a class="header-anchor" href="#permission" aria-label="Permalink to &quot;Permission&quot;">​</a></h3><p>Like other network tools, <code>custom_search</code> will ask for your confirmation before running unless you have <code>always_allow_tool_actions</code> set to <code>true</code> in your agent settings.</p><hr><h2 id="feature-2-slash-command-custom-search" tabindex="-1">Feature 2: Slash Command (<code>/custom-search</code>) <a class="header-anchor" href="#feature-2-slash-command-custom-search" aria-label="Permalink to &quot;Feature 2: Slash Command (\`/custom-search\`)&quot;">​</a></h2><p>The <code>/custom-search</code> slash command lets <strong>you</strong> manually trigger a query from the Assistant panel&#39;s message input. It inserts the raw JSON results directly into the conversation as context for the model.</p><h3 id="how-to-use-it" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><p>In the Assistant panel (old thread view), type:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/custom-search your query here</span></span></code></pre></div><p>For example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/custom-search level:error AND service:payments</span></span></code></pre></div><p>The results are fetched immediately and inserted into the thread as a formatted JSON code block, which the model can then read and reason about.</p><h3 id="when-to-use-the-slash-command-vs-the-agent-tool" tabindex="-1">When to use the slash command vs. the agent tool <a class="header-anchor" href="#when-to-use-the-slash-command-vs-the-agent-tool" aria-label="Permalink to &quot;When to use the slash command vs. the agent tool&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th><code>/custom-search</code> slash command</th><th><code>custom_search</code> agent tool</th></tr></thead><tbody><tr><td><strong>Triggered by</strong></td><td>You, manually</td><td>The AI model, automatically</td></tr><tr><td><strong>Where</strong></td><td>Assistant panel message input</td><td>Agent panel (autonomous agent)</td></tr><tr><td><strong>Output</strong></td><td>JSON inserted into thread</td><td>Tool result shown as a card in the Agent panel</td></tr><tr><td><strong>Use case</strong></td><td>When you want to provide search data as context yourself</td><td>When you want the agent to search your endpoint as part of a larger task</td></tr></tbody></table><hr><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Both the slash command and the agent tool read from the same configuration block inside your <code>settings.json</code>.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>First-Time Installation:</strong> This setting may get reset when you install Zed Custom for the first time. If you want to use the default <code>doc-search.dev</code> capabilities, note that you will need to manually add the current search URL and port: <code>http://52.179.183.195:9200</code>.</p></div><p>You can add this URL using two methods:</p><h3 id="method-1-using-the-assistant-panel-ui-recommended" tabindex="-1">Method 1: Using the Assistant Panel UI (Recommended) <a class="header-anchor" href="#method-1-using-the-assistant-panel-ui-recommended" aria-label="Permalink to &quot;Method 1: Using the Assistant Panel UI (Recommended)&quot;">​</a></h3><p>Zed Custom includes a direct UI shortcut for adding your search endpoint so you don&#39;t even have to write JSON manually!</p><ol><li>Open the <strong>Assistant Panel</strong> (the chat panel).</li><li>Click the <strong>Gear icon</strong> (Settings) at the top right of the Assistant panel to open the underlying configuration modal.</li><li>Scroll down past your Agent Profiles to find a section titled <strong>&quot;Custom Search&quot;</strong> (with the description <em>&quot;Configure your own search endpoint for agent tools.&quot;</em>).</li><li>Click the small <strong>Arrow (Open)</strong> icon next to the title. This is wired up directly to Zed&#39;s settings editor and will instantly open your <code>settings.json</code> file and drop your cursor precisely where the custom search configuration belongs!</li></ol><h3 id="method-2-manually-in-settings-json" tabindex="-1">Method 2: Manually in <code>settings.json</code> <a class="header-anchor" href="#method-2-manually-in-settings-json" aria-label="Permalink to &quot;Method 2: Manually in \`settings.json\`&quot;">​</a></h3><p>If you want to add it manually without clicking through the UI, open your Zed <code>settings.json</code> (using <code>Cmd-,</code>), and look for the <code>&quot;agent&quot;</code> object. Add the <code>&quot;custom_search&quot;</code> key inside of it like this:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;agent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;custom_search&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      // Add your actual URL here (e.g., Elasticsearch, Algolia endpoint)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;endpoint_url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://52.179.183.195:9200&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      </span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      // Optional API Key for Authorization</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;api_key&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;YOUR_API_KEY_HERE&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Setting</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>endpoint_url</code></td><td><strong>Yes</strong></td><td>Full HTTP URL to your search endpoint (e.g., Elasticsearch <code>_search</code> endpoint).</td></tr><tr><td><code>api_key</code></td><td>No</td><td>API key sent as <code>Authorization: ApiKey &lt;key&gt;</code>. Omit if authentication is not required.</td></tr></tbody></table><blockquote><p><strong>Both features stop working and return an error if <code>endpoint_url</code> is not set.</strong> The <code>api_key</code> is optional.</p></blockquote><hr><h2 id="example-using-both-together" tabindex="-1">Example: Using Both Together <a class="header-anchor" href="#example-using-both-together" aria-label="Permalink to &quot;Example: Using Both Together&quot;">​</a></h2><p>A typical workflow might combine both: you use <code>/custom-search</code> to do a quick investigation first, then ask the agent to take action on the results — at which point it may call <code>custom_search</code> on its own for follow-up queries.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/custom-search service:checkout AND status:500 AND @timestamp:[now-1h TO now]</span></span></code></pre></div><p>Then in a follow-up message:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Based on those results, investigate why the checkout service is failing and suggest a fix.</span></span></code></pre></div><p>The agent will understand the context you provided via <code>/custom-search</code> and may issue additional <code>custom_search</code> calls autonomously as it investigates.</p>`,44)])])}const g=e(n,[["render",i]]);export{p as __pageData,g as default};
